def verify_trust_proof_synced(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """以同步锚点验真外部谓词证明，返回 (是否有效, 失败原因)。

    请求结构（恰含 signer_did/at/proof/challenge/source_tenant_id
    及类型）由服务层校验（400）。本方法假定五键类型已合法：
    - 该签名方在本租户无同步检查点（含跨租户）抛 NotFoundError；
      at 超过检查点抛 ConflictError；
    - 证明九字段、predicates、results、challenge 与 expires_at
      规则沿用 :meth:`verify_trust_proof`；
    - 锚点取该来源 cursor<=at 的已同步事件，以 (issuer_did, 版本)
      最后事件为准；缺失、非 active 或 uses 无 proof 均返回
      (False, "同步锚点不可用")；
    - proof 须为 ES256、64 字节裸 R||S 无填充 base64url，覆盖除
      proof 外八字段并加入 tenant_id=source_tenant_id 的规范化
      JSON；格式错、验签错、到期依次返回 “签名格式错误”/
      “签名校验失败”/“证明已过期”，较早错误优先。

    校验顺序：请求 -> 证明字段 -> 挑战 -> 锚点 -> 签名格式 ->
    验签 -> 期限。纯只读：不改同步页、检查点、锚点、证明、状态或
    审计，结论随状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    return self._verify_synced_proof_against(
        latest, proof, challenge, source_tenant_id
    )

@staticmethod
def _verify_synced_proof_against(
    latest: Dict[Tuple[str, int], Dict[str, Any]],
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """在已解析的同步锚点快照上验真一条外部谓词证明（只读）。

    假定 proof 为 JSON 对象、challenge 与 source_tenant_id 均为非空
    字符串；证明九字段、谓词/results、RFC6901 路径、挑战、锚点、
    签名覆盖（去掉 proof 后的八字段并加入
    tenant_id=source_tenant_id 的规范化 JSON）、签名格式、验签与
    期限规则及原因分类与 :meth:`verify_trust_proof_synced` 完全
    一致，供单条与批量同步锚点验真共用同一快照。
    """
    # 证明字段（沿用 /v1/trust/proofs/verify 的分类原因）：恰为
    # prove 响应九字段。
    required_fields = {
        "proof_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "predicates",
        "results",
        "challenge",
        "expires_at",
        "proof",
    }
    if set(proof) != required_fields:
        missing = sorted(required_fields - set(proof))
        if missing:
            return False, f"证明缺少字段: {', '.join(missing)}"
        extra = sorted(set(proof) - required_fields)
        return False, f"证明含多余字段: {', '.join(extra)}"
    for field in ("proof_id", "credential_id", "issuer_did"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    key_version = proof["issuer_key_version"]
    if (
        not isinstance(key_version, int)
        or isinstance(key_version, bool)
        or key_version < 1
    ):
        return False, "证明字段 issuer_key_version 必须为正整数"
    predicates = proof["predicates"]
    if not isinstance(predicates, list) or not predicates:
        return False, "证明字段 predicates 必须为非空数组"
    seen_tokens: List[Tuple[str, ...]] = []
    for item in predicates:
        if not isinstance(item, dict):
            return False, "证明 predicates 元素必须为 JSON 对象"
        if set(item) - {"path", "op", "value"}:
            extra = sorted(set(item) - {"path", "op", "value"})
            return False, (
                f"证明 predicates 元素含多余字段: {', '.join(extra)}"
            )
        if "path" not in item:
            return False, "证明 predicates 元素缺少字段: path"
        if "op" not in item:
            return False, "证明 predicates 元素缺少字段: op"
        op = item["op"]
        if op not in _PREDICATE_OPS:
            return False, (
                f"证明 predicates 元素 op 非法: {op!r}"
                "（仅支持 exists/eq/gte/lte）"
            )
        if op == "exists":
            if "value" in item:
                return False, (
                    "证明 predicates 元素 op 为 exists 时禁止 value 字段"
                )
        elif "value" not in item:
            return False, (
                f"证明 predicates 元素 op 为 {op} 时缺少字段: value"
            )
        elif op in ("gte", "lte") and not _is_number(item["value"]):
            return False, (
                f"证明 predicates 元素 op 为 {op} 时 value 必须为非布尔数字"
            )
        # 仅做指针语法与重叠校验：不查 claims 命中、不判数组路径。
        try:
            tokens = _parse_pointer(item["path"], "证明 predicates")
        except ValidationError as exc:
            return False, str(exc)
        if tokens in seen_tokens:
            return False, (
                f"证明 predicates 路径重复: {item['path']!r}"
            )
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"{item['path']!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"已选路径被 {item['path']!r} 覆盖"
                )
        seen_tokens.append(tokens)
    results = proof["results"]
    if not isinstance(results, list) or len(results) != len(predicates):
        return False, (
            "证明字段 results 必须为与 predicates 等长的数组"
        )
    if any(not isinstance(item, bool) for item in results):
        return False, "证明字段 results 仅能包含布尔值"
    for field in ("challenge", "expires_at", "proof"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"

    # 挑战：请求 challenge 须等于证明 challenge。
    if challenge != proof["challenge"]:
        return False, "挑战不匹配: 请求 challenge 与证明 challenge 不一致"

    # 同步锚点：(issuer_did, 版本) 最后事件，须 active 且含 proof
    # 用途。
    issuer_did = proof["issuer_did"]
    anchor = latest.get((issuer_did, key_version))
    if (
        anchor is None
        or anchor["status"] != "active"
        or "proof" not in anchor["uses"]
    ):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON
    public_pem = anchor["public_key"]
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON

    # 签名格式（严格：64 字节裸 R||S 无填充 base64url）与密码学
    # 验签：覆盖范围沿用 /v1/trust/proofs/verify——去掉 proof 后的
    # 八个字段并加入 tenant_id=source_tenant_id。
    signature = proof["proof"]
    message = {k: v for k, v in proof.items() if k != "proof"}
    message["tenant_id"] = source_tenant_id
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    try:
        crypto.verify(message, signature, public_pem)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    except crypto.InvalidSignature:
        return False, IMPORTED_SIGNATURE_INVALID_REASON
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, IMPORTED_SIGNATURE_INVALID_REASON

    # 期限：expires_at 须为 UTC 秒精度 Z 格式；当前时间达到它即
    # 过期。规则同 /v1/trust/proofs/verify。
    expires_value = proof["expires_at"]
    if (
        not isinstance(expires_value, str)
        or not _UTC_Z_SHAPE_RE.match(expires_value)
    ):
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        expires_dt = _parse_utc_z(expires_value)
    except ValueError:
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    if datetime.now(timezone.utc) >= expires_dt:
        return False, "证明已过期"
    return True, ""

def verify_trust_proofs_synced_batch(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    items: Any,
) -> List[Dict[str, Any]]:
    """批量以同一同步锚点快照验真外部谓词证明，返回逐项结果。

    请求级结构（恰含 signer_did/at/proofs、类型与 1–100 项上限）
    由服务层校验（400）。本方法假定三者类型已合法：
    - 检查点语义与 :meth:`verify_trust_proof_synced` 一致：来源未
      同步（含跨租户）抛 NotFoundError，at 超检查点抛
      ConflictError；合法时按 cursor<=at 解析一次快照，整批共用；
    - 逐项不短路、等长同序：项须恰含 proof（JSON 对象）、
      challenge（非空字符串）、source_tenant_id（非空字符串），
      否则该项 ``{"valid": false, "reason": "请求项非法"}``；合法
      项复用单条 verify-synced 的证明九字段、谓词/results、
      RFC6901 路径、挑战、签名覆盖、锚点、格式、验签与期限规则及
      原因分类；
    - 成功项仅 ``{"valid": true}``，失败项键序为 valid、reason。

    纯只读：不改同步页、检查点、锚点、证明、状态或审计，结论随
    状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    results: List[Dict[str, Any]] = []
    for item in items:  # 逐项处理，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"proof", "challenge", "source_tenant_id"}
            or not isinstance(item["proof"], dict)
            or not isinstance(item["challenge"], str)
            or not item["challenge"]
            or not isinstance(item["source_tenant_id"], str)
            or not item["source_tenant_id"]
        ):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        valid, reason = self._verify_synced_proof_against(
            latest,
            item["proof"],
            item["challenge"],
            item["source_tenant_id"],
        )
        if valid:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    return results

def verify_trust_proofs_synced_batch_with_status(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    items: Any,
) -> List[Dict[str, Any]]:
    """批量以同步锚点快照验真外部谓词证明并合并批初状态快照。

    请求级结构（恰含 signer_did/at/proofs、类型与 1–100 项上限）
    由服务层校验（400）。本方法假定三者类型已合法：
    - 检查点语义与 :meth:`verify_trust_proofs_synced_batch` 一致：
      来源未同步（含跨租户）抛 NotFoundError，at 超检查点抛
      ConflictError，均先于逐项校验；合法时按 cursor<=at 解析一次
      锚点快照，并在批初同一次原子读取本租户
      ``credential_status_sync`` 状态快照，整批共用；
    - 逐项不短路、等长同序：项须恰含 proof（JSON 对象）、
      challenge（非空字符串）、source_tenant_id（非空字符串），
      否则该项 ``{"valid": false, "reason": "请求项非法"}``；合法
      项复用单条 verify-synced 的证明九字段、谓词/results、
      RFC6901 路径、挑战、cursor<=at 末锚点、签名覆盖、格式、验签
      与期限规则及原因分类；
    - 验真通过后按证明的 ``(issuer_did, credential_id)`` 查批初
      状态快照：未同步（含属他租户）为“外部凭证状态未同步”，
      revoked 为“外部凭证已吊销：<保存的 reason>”（保存记录无
      reason 时用“未知原因”），unknown 为“外部凭证状态未知”，
      active 判成功；
    - 成功项仅 ``{"valid": true}``，失败项键序为 valid、reason。

    纯只读：不改同步页、检查点、锚点、证明、状态或审计，结论随
    状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    with self._lock:  # 批初一次原子读取本租户状态快照，整批共用
        bucket = self._bucket_locked(tenant_id)
        status_rows: Dict[str, Dict[str, Dict[str, Any]]] = {}
        if bucket is not None:
            for issuer, rows in (
                bucket.get("credential_status_sync", {}).items()
            ):
                status_rows[issuer] = {
                    cid: dict(row) for cid, row in rows.items()
                }
    results: List[Dict[str, Any]] = []
    for item in items:  # 逐项处理，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"proof", "challenge", "source_tenant_id"}
            or not isinstance(item["proof"], dict)
            or not isinstance(item["challenge"], str)
            or not item["challenge"]
            or not isinstance(item["source_tenant_id"], str)
            or not item["source_tenant_id"]
        ):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        proof = item["proof"]
        valid, reason = self._verify_synced_proof_against(
            latest,
            proof,
            item["challenge"],
            item["source_tenant_id"],
        )
        if valid:
            row = status_rows.get(
                proof["issuer_did"], {}
            ).get(proof["credential_id"])
            if row is None:
                valid, reason = False, "外部凭证状态未同步"
            else:
                status = row.get("status")
                if status == "revoked":
                    saved_reason = row.get("reason")
                    if not saved_reason:
                        saved_reason = "未知原因"
                    valid, reason = (
                        False,
                        f"外部凭证已吊销：{saved_reason}",
                    )
                elif status != "active":
                    # status 仅可能为 active/revoked/unknown
                    # （同步入口已约束）。
                    valid, reason = False, "外部凭证状态未知"
        if valid:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    return results

